package cn.kaoyan.assistant;
import android.content.ContentValues;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import android.util.AtomicFile;import org.json.*;import java.io.*;import java.util.*;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;
final class LearningStore {
 private final SQLiteDatabase db;private final File legacy;
 LearningStore(File root)throws Exception{legacy=new File(root,"learning.json");db=SQLiteDatabase.openOrCreateDatabase(new File(root,"learning.db"),null);db.enableWriteAheadLogging();db.execSQL("CREATE TABLE IF NOT EXISTS meta (key TEXT PRIMARY KEY,value TEXT NOT NULL)");db.execSQL("CREATE TABLE IF NOT EXISTS records (kind TEXT,id TEXT,position INTEGER,hash TEXT,meta TEXT,PRIMARY KEY(kind,id))");db.execSQL("CREATE TABLE IF NOT EXISTS texts (owner TEXT,slot TEXT,part INTEGER,value TEXT,PRIMARY KEY(owner,slot,part))");db.execSQL("CREATE VIRTUAL TABLE IF NOT EXISTS text_search USING fts4(owner,slot,part,value,content='texts',tokenize=unicode61)");db.execSQL("CREATE TRIGGER IF NOT EXISTS texts_ai AFTER INSERT ON texts WHEN new.owner NOT LIKE '@%' AND new.owner NOT LIKE 'undoRecords:%' BEGIN INSERT INTO text_search(docid,owner,slot,part,value) VALUES(new.rowid,new.owner,new.slot,new.part,new.value); END");db.execSQL("CREATE TRIGGER IF NOT EXISTS texts_bd BEFORE DELETE ON texts WHEN old.owner NOT LIKE '@%' AND old.owner NOT LIKE 'undoRecords:%' BEGIN DELETE FROM text_search WHERE docid=old.rowid; END");if(!hasState()&&(legacy.exists()||new File(root,"learning.json.bak").exists())){try(InputStream in=new AtomicFile(legacy).openRead()){save(new JSONObject(read(in,ArchiveIO.MAX_STATE)));}}}
 private boolean hasState(){try(Cursor c=db.rawQuery("SELECT 1 FROM meta WHERE key='state'",null)){return c.moveToFirst();}}
 static String read(InputStream in,int max)throws IOException{ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1){if(out.size()+n>max)throw new IOException("学习记录超过当前内存读取额度");out.write(b,0,n);}return out.toString("UTF-8");}
 private static String hash(String value)throws Exception{byte[] bytes=MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));StringBuilder s=new StringBuilder();for(byte b:bytes)s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
 private void text(String owner,String slot,String value){for(int start=0,part=0;start<value.length();part++){int end=Math.min(value.length(),start+16000);if(end<value.length()&&Character.isHighSurrogate(value.charAt(end-1)))end--;ContentValues row=new ContentValues();row.put("owner",owner);row.put("slot",slot);row.put("part",part);row.put("value",value.substring(start,end));db.insertOrThrow("texts",null,row);start=end;}}
 private String text(String owner,String slot){StringBuilder out=new StringBuilder();try(Cursor c=db.rawQuery("SELECT value FROM texts WHERE owner=? AND slot=? ORDER BY part",new String[]{owner,slot})){while(c.moveToNext())out.append(c.getString(0));}return out.toString();}
 synchronized void save(JSONObject state)throws Exception{JSONObject head=new JSONObject(state.toString());head.remove("assistant");Set<String> kinds=new HashSet<>(Arrays.asList("tasks","notes","mistakes","files","undoRecords"));db.beginTransaction();try{for(String kind:kinds){JSONArray items=state.optJSONArray(kind);if(items==null)items=new JSONArray();Set<String> seen=new HashSet<>();Map<String,String> existing=new HashMap<>(),positions=new HashMap<>();try(Cursor c=db.rawQuery("SELECT id,hash,position FROM records WHERE kind=?",new String[]{kind})){while(c.moveToNext()){existing.put(c.getString(0),c.getString(1));positions.put(c.getString(0),c.getString(2));}}for(int i=0;i<items.length();i++){JSONObject item=items.getJSONObject(i);String id=item.getString("id"),owner=kind+":"+id;if(!seen.add(id))throw new IOException("存在重复学习记录ID");String fingerprint=hash(item.toString());if(fingerprint.equals(existing.get(id))){if(String.valueOf(i).equals(positions.get(id)))continue;ContentValues position=new ContentValues();position.put("position",i);db.update("records",position,"kind=? AND id=?",new String[]{kind,id});continue;}JSONObject meta=new JSONObject(item.toString());String body=meta.optString("body");meta.remove("body");db.delete("texts","owner=?",new String[]{owner});JSONArray pages=meta.optJSONArray("pages");StringBuilder combined=new StringBuilder();if(pages!=null){for(int j=0;j<pages.length();j++){JSONObject page=pages.getJSONObject(j);String value=page.optString("body");combined.append(value);text(owner,"page:"+j,value);page.remove("body");}}if(pages!=null&&body.equals(combined.toString()))meta.put("_bodyFromPages",true);else text(owner,"body",body);ContentValues row=new ContentValues();row.put("kind",kind);row.put("id",id);row.put("position",i);row.put("hash",fingerprint);row.put("meta",meta.toString());db.insertWithOnConflict("records",null,row,SQLiteDatabase.CONFLICT_REPLACE);}for(String id:existing.keySet())if(!seen.contains(id)){db.delete("records","kind=? AND id=?",new String[]{kind,id});db.delete("texts","owner=?",new String[]{kind+":"+id});}head.remove(kind);}ContentValues row=new ContentValues();row.put("key","state");db.delete("texts","owner=?",new String[]{"@state"});text("@state","head",head.toString());row.put("value","{\"chunked\":true}");db.insertWithOnConflict("meta",null,row,SQLiteDatabase.CONFLICT_REPLACE);db.setTransactionSuccessful();}finally{db.endTransaction();}}
 synchronized boolean canDelete(String path)throws Exception{JSONObject state;try(Cursor c=db.rawQuery("SELECT value FROM meta WHERE key='state'",null)){if(!c.moveToFirst())return false;state=new JSONObject(c.getString(0));if(state.optBoolean("chunked"))state=new JSONObject(text("@state","head"));}JSONArray pending=state.optJSONArray("pendingFileDeletes");boolean queued=false;if(pending!=null)for(int i=0;i<pending.length();i++)if(path.equals(pending.optString(i)))queued=true;if(!queued)return false;JSONObject undo=state.optJSONObject("organizationUndo");JSONArray protectedPaths=undo==null?null:undo.optJSONArray("protectedPaths");if(protectedPaths!=null)for(int i=0;i<protectedPaths.length();i++)if(path.equals(protectedPaths.optString(i)))return false;try(Cursor c=db.rawQuery("SELECT meta FROM records WHERE kind='files'",null)){while(c.moveToNext())if(path.equals(new JSONObject(c.getString(0)).optString("path")))return false;}return true;}
 synchronized JSONArray search(String query)throws Exception{String[] words=query.replaceAll("[^\\p{L}\\p{N}]+"," ").trim().split(" +");StringBuilder match=new StringBuilder();for(int i=0;i<Math.min(words.length,8);i++){String word=words[i];if(word.length()<2)continue;if(word.length()>80)word=word.substring(0,80);if(match.length()>0)match.append(" OR ");match.append(word).append('*');}JSONArray result=new JSONArray();if(match.length()==0)return result;try(Cursor c=db.rawQuery("SELECT DISTINCT owner FROM text_search WHERE text_search MATCH ? LIMIT 40",new String[]{match.toString()})){while(c.moveToNext())result.put(c.getString(0));}return result;}
 synchronized JSONObject load()throws Exception{if(!hasState())return new JSONObject();JSONObject state=new JSONObject();try(Cursor c=db.rawQuery("SELECT value FROM meta WHERE key='state'",null)){if(c.moveToFirst()){state=new JSONObject(c.getString(0));if(state.optBoolean("chunked"))state=new JSONObject(text("@state","head"));}}for(String kind:Arrays.asList("tasks","notes","mistakes","files","undoRecords")){JSONArray items=new JSONArray();try(Cursor c=db.rawQuery("SELECT id,meta FROM records WHERE kind=? ORDER BY position",new String[]{kind})){while(c.moveToNext()){String owner=kind+":"+c.getString(0);JSONObject item=new JSONObject(c.getString(1));JSONArray pages=item.optJSONArray("pages");StringBuilder body=new StringBuilder();if(pages!=null)for(int j=0;j<pages.length();j++){String value=text(owner,"page:"+j);pages.getJSONObject(j).put("body",value);body.append(value);}String value=item.optBoolean("_bodyFromPages")?body.toString():text(owner,"body");item.remove("_bodyFromPages");if(!value.isEmpty()||kind.equals("notes")||kind.equals("mistakes")||pages!=null)item.put("body",value);items.put(item);}}state.put(kind,items);}return state;}
}
